# envcfg.py

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        import tomllib
        with open(toml_path, 'rb') as f:
            config.update(tomllib.load(f))
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            nested_key = key[len(env_prefix):].replace('__', '.').lower()
            config = set_nested_key(config, nested_key, coerce(value))
    return config

def set_nested_key(d, key, value):
    keys = key.split('.')
    for k in keys[:-1]:
        d = d.setdefault(k, {})
    d[keys[-1]] = value
    return d

def coerce(value):
    if value.isdigit():
        return int(value)
    elif value.lower() in ['true', 'yes', '1']:
        return True
    elif value.lower() in ['false', 'no', '0']:
        return False
    else:
        return value

class ConfigError(Exception):
    pass

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'server': {'port': 8080}}
    config = load_config(defaults)
    assert config == {'server': {'port': 8080}}

def test_toml_file(tmp_path):
    toml_path = tmp_path / 'config.toml'
    toml_path.write_text('server = {port = 9090}')
    defaults = {'server': {'port': 8080}}
    config = load_config(defaults, toml_path=str(toml_path))
    assert config == {'server': {'port': 9090}}

def test_env_variables():
    import os
    os.environ['APP__SERVER__PORT'] = '7070'
    defaults = {'server': {'port': 8080}}
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'server': {'port': 7070}}

def test_coercion():
    import os
    os.environ['APP__SERVER__PORT'] = '80'
    defaults = {'server': {'port': 8080}}
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'server': {'port': 80}}

def test_missing_toml_file(tmp_path):
    toml_path = tmp_path / 'config.toml'
    defaults = {'server': {'port': 8080}}
    config = load_config(defaults, toml_path=str(toml_path))
    assert config == {'server': {'port': 8080}}

def test_missing_default_key():
    import os
    os.environ['APP__SERVER__PORT'] = '7070'
    defaults = {}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

def test_invalid_coercion():
    import os
    os.environ['APP__SERVER__PORT'] = 'invalid'
    defaults = {'server': {'port': 8080}}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

